def is_valid_hsl_tuple(t):
    if not isinstance(t, tuple):
        return False
    if len(t) != 3:
        return False
    hue, sat, light = t
    if not isinstance(hue, int) or isinstance(hue, bool):
        return False
    if not (0 <= hue <= 360):
        return False
    for v in (sat, light):
        if not isinstance(v, (int, float)) or isinstance(v, bool):
            return False
        if not (0 <= v <= 100):
            return False
    return True

def is_monotonic_increasing(seq):
    for i in range(1, len(seq)):
        if not (seq[i] > seq[i - 1]):
            return False
    return True

def is_monotonic_decreasing(seq):
    for i in range(1, len(seq)):
        if not (seq[i] < seq[i - 1]):
            return False
    return True

def is_monotonic_nonincreasing(seq):
    for i in range(1, len(seq)):
        if not (seq[i] <= seq[i - 1]):
            return False
    return True

