def is_valid_port_range(s):
    m = re.fullmatch(r'(0|[1-9]\d*)-(0|[1-9]\d*)', s)
    if not m:
        return False
    a, b = int(m.group(1)), int(m.group(2))
    if not (0 <= a <= 65535) or not (0 <= b <= 65535):
        return False
    return a <= b

def is_valid_pin_code(s):
    if len(s) != 4 or not s.isdigit():
        return False
    digits = [int(c) for c in s]
    if len(set(digits)) == 1:
        return False
    ascending = all(digits[i] + 1 == digits[i + 1] for i in range(3))
    descending = all(digits[i] - 1 == digits[i + 1] for i in range(3))
    if ascending or descending:
        return False
    return True

