def is_valid_utc_offset(s):
    m = re.fullmatch(r'([+-])(\d{2}):(\d{2})', s)
    if not m:
        return False
    sign, hh, mm = m.group(1), int(m.group(2)), int(m.group(3))
    total = hh * 60 + mm
    if sign == '-':
        total = -total
    return -720 <= total <= 840
